export function App() {
  const canvasRef = useRef(null);
  const sceneRef = useRef(null);
  const lenisRef = useRef(null);

  const [loadProgress, setLoadProgress] = useState(0);
  const [sceneReady, setSceneReady] = useState(false);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [activeActIdx, setActiveActIdx] = useState(0);

  // Interactive 3D <-> UI states
  const [digestMode, setDigestMode] = useState('digest');
  const [anchorScenario, setAnchorScenario] = useState('insert');
  const [selectedHarnessIdx, setSelectedHarnessIdx] = useState(0);

  // Initialize Three.js EvidenceScene
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;

    const engine = new EvidenceScene(canvas, {
      onProgress: (p) => setLoadProgress(p),
      onReady: () => {
        setLoadProgress(1);
        setTimeout(() => setSceneReady(true), 180);
      },
      onAutoAnchorScenario: (scen) => setAnchorScenario(scen),
      onHarnessSelect: (idx) => setSelectedHarnessIdx(idx),
    });
    sceneRef.current = engine;

    return () => {
      engine.dispose();
      sceneRef.current = null;
    };
  }, []);

  // Initialize Lenis smooth scroll + GSAP ScrollTrigger reveals
  useEffect(() => {
    const lenis = new Lenis({
      duration: 1.15,
      easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
      orientation: 'vertical',
      gestureOrientation: 'vertical',
      smoothWheel: true,
      wheelMultiplier: 0.95,
      touchMultiplier: 1.35,
    });
    lenisRef.current = lenis;

    const syncScroll = () => {
      const maxScroll = Math.max(
        1,
        document.documentElement.scrollHeight - window.innerHeight
      );
      const raw = Math.max(0, Math.min(1, window.scrollY / maxScroll));
      setScrollProgress(raw);
      setActiveActIdx(actIndexForProgress(raw));
      if (sceneRef.current) {
        sceneRef.current.setScrollProgress(raw);
      }
      ScrollTrigger.update();
    };

    lenis.on('scroll', syncScroll);
    window.addEventListener('scroll', syncScroll, { passive: true });
    window.addEventListener('resize', syncScroll);
    syncScroll();

    let rafId = 0;
    const raf = (time) => {
      lenis.raf(time);
      rafId = requestAnimationFrame(raf);
    };
    rafId = requestAnimationFrame(raf);

    // Subtle GSAP editorial panel reveals tied to scroll
    const ctx = gsap.context(() => {
      gsap.utils.toArray('.evidence-panel').forEach((panel) => {
        gsap.fromTo(
          panel,
          { opacity: 0.25, y: 28 },
          {
            opacity: 1,
            y: 0,
            duration: 0.7,
            ease: 'power3.out',
            scrollTrigger: {
              trigger: panel,
              start: 'top 84%',
              end: 'top 42%',
              scrub: 0.4,
            },
          }
        );
      });
    });

    return () => {
